import { useEffect, useState } from "react";
import styles from "./IncidentsPage.module.css";
import { incidents as mockIncidents } from "../../mock/incidents";
import { fetchHotTickets } from "../../api/alerts";

const ITEMS_PER_PAGE = 10;

export const IncidentsPage = () => {
  const [page, setPage] = useState(1);
  const [hotTickets, setHotTickets] = useState<number[]>([]);

  useEffect(() => {
    loadHotTickets();
  }, []);

  const loadHotTickets = async () => {
    const data = await fetchHotTickets();
    setHotTickets(data);
  };

  const start = (page - 1) * ITEMS_PER_PAGE;
  const paginated = mockIncidents.slice(start, start + ITEMS_PER_PAGE);

  return (
    <div className={styles.page}>
      {/* Header */}
      <header className={styles.header}>
        <h1>Система управления инцидентами</h1>
        <button className={styles.primaryBtn}>+ Создать инцидент</button>
      </header>

      {/* Top */}
      <section className={styles.topSection}>
        <div className={styles.card}>
          <h3>Информационные сообщения</h3>
          <p className={styles.infoTitle}>
            Telegram Bot временно недоступен
          </p>
          <p className={styles.infoText}>
            Проводится обновление, бот возобновит работу до 15:00
          </p>
        </div>

        <div className={`${styles.card} ${styles.alertCard}`}>
          <div className={styles.alertHeader}>
            <h3>Оповещения</h3>
            <button onClick={loadHotTickets}>Обновить</button>
          </div>

          <p>Горящие тикеты:</p>

          <ul className={styles.alertList}>
            {hotTickets.map((id) => (
              <li key={id}>{id}</li>
            ))}
          </ul>

          <span className={styles.alertHint}>
            Тикеты будут просрочены менее чем через 4 часа
          </span>
        </div>
      </section>

      {/* Table */}
      <section className={styles.tableCard}>
        <div className={styles.tableHeader}>
          <h3>Список инцидентов</h3>
          <span>
            Показано {start + 1}–
            {Math.min(start + ITEMS_PER_PAGE, mockIncidents.length)} из{" "}
            {mockIncidents.length}
          </span>
        </div>

        <table className={styles.table}>
          <thead>
            <tr>
              <th>Номер ТТ</th>
              <th>Дата создания</th>
              <th>Приоритет</th>
              <th>Описание</th>
              <th>Состояние услуги</th>
              <th>Состояние ТТ</th>
              <th>Филиал</th>
            </tr>
          </thead>

          <tbody>
            {paginated.map((item) => (
              <tr key={item.id}>
                <td>{item.id}</td>
                <td>{item.createdAt}</td>
                <td>
                  <span className={`${styles.priority} ${styles[`p${item.priority}`]}`}>
                    {item.priority}
                  </span>
                </td>
                <td>{item.description}</td>
                <td
                  className={
                    item.serviceStatus === "Недоступна"
                      ? styles.down
                      : styles.up
                  }
                >
                  {item.serviceStatus}
                </td>
                <td>{item.ticketStatus}</td>
                <td>{item.branch}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Pagination */}
        <div className={styles.pagination}>
          <button
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Назад
          </button>

          <span>{page}</span>

          <button
            disabled={start + ITEMS_PER_PAGE >= mockIncidents.length}
            onClick={() => setPage((p) => p + 1)}
          >
            Вперёд
          </button>
        </div>
      </section>
    </div>
  );
};
